INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1300, 'compensate', '/ˈkɒmpenseɪt/', 'verb', '{"zh-TW":["補償；賠償"],"en":["to give something to make up for loss or damage"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"pens","meaning":"weigh (稱重)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"完全衡量損失並補回，即「補償」。"}', 'compensate for / compensate employees', '[{"en":"The company compensated employees for overtime work.","zh-TW":"公司補償員工加班工作。"},{"en":"Nothing can compensate for the loss of reputation.","zh-TW":"沒有什麼能彌補名譽的損失。"},{"en":"The company compensated workers for overtime.","zh-TW":"公司補償了員工的加班費。"},{"en":"Nothing can compensate for the loss of a loved one.","zh-TW":"沒有什麼能彌補失去親人的痛苦。"}]', '{"noun":"compensation"}', NULL, 4, 1300, 656),
(1301, 'compensation', '/ˌkɒmpənˈseɪʃən/', 'noun', '{"zh-TW":["薪酬；補償"],"en":["total financial and non-financial rewards provided to employees"]}', NULL, 'compensation package / compensation structure / executive compensation', '[{"en":"The compensation package includes salary, bonuses, and benefits.","zh-TW":"薪酬方案包括薪資、獎金和福利。"},{"en":"Competitive compensation is key to attracting top talent.","zh-TW":"具競爭力的薪酬是吸引頂尖人才的關鍵。"}]', '{"verb":"compensate","adjective":"compensatory"}', NULL, 4, 1301, 85),
(1302, 'compensation package', '/ˌkɒmpənˈseɪʃən ˈpækɪdʒ/', 'noun', '{"zh-TW":["薪酬套餐"],"en":["the total remuneration offered to an employee including salary and benefits"]}', NULL, 'offer a compensation package / compensation package negotiation', '[{"en":"The compensation package includes base salary, bonus, and stock options.","zh-TW":"薪酬套餐包括基本薪資、獎金和股票選擇權。"},{"en":"The CEO negotiated a competitive compensation package before joining.","zh-TW":"執行長在加入前談判了有競爭力的薪酬套餐。"}]', NULL, NULL, 5, 1302, NULL),
(1303, 'compensatory', '/kəmˈpensətəri/', 'adjective', '{"zh-TW":["補償性的；賠償性的"],"en":["intended to compensate for loss or injury"]}', NULL, 'compensatory damages / compensatory measure / compensatory mechanism', '[{"en":"Compensatory damages were awarded to cover the plaintiff''s lost earnings.","zh-TW":"判定補償性損害賠償以彌補原告的損失收入。"},{"en":"The policy included compensatory measures to support workers displaced by automation.","zh-TW":"該政策包括補償措施，以支持被自動化取代的工人。"}]', NULL, NULL, 4, 1303, NULL),
(1304, 'compensatory damages', '/kɒmˈpensətɔːri ˈdæmɪdʒɪz/', 'noun', '{"zh-TW":["補償性損害賠償"],"en":["monetary compensation awarded to restore a party to its original position"]}', NULL, 'award compensatory damages / seek compensatory damages', '[{"en":"The court awarded compensatory damages of $200,000 for lost profits.","zh-TW":"法院判給了20萬元的補償性損害賠償以補償利潤損失。"},{"en":"Compensatory damages aim to make the injured party whole.","zh-TW":"補償性損害賠償旨在使受害方恢復原狀。"}]', '{"opposite":"punitive damages"}', NULL, 5, 1304, NULL),
(1305, 'compete', '/kəmˈpiːt/', 'verb', '{"zh-TW":["競爭","競爭；比賽"],"en":["to strive to gain something by defeating others","to try to win something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pete","meaning":"seek (尋求)"},"logic":"一起尋求同一目標，即「競爭」。"}', 'compete with/against / compete for; compete against / compete for', '[{"en":"Local firms must compete with international corporations.","zh-TW":"本地企業必須與國際公司競爭。"},{"en":"Ten candidates competed for the position.","zh-TW":"十位候選人競爭該職位。"},{"en":"Ten teams will compete in the tournament.","zh-TW":"十支隊伍將參加比賽。"},{"en":"Companies compete for customers.","zh-TW":"公司為爭取客戶而競爭。"}]', '{"noun":"competition","adjective":"competitive","noun2":"competitor"}', NULL, 3, 1305, NULL),
(1306, 'competent', '/ˈkɒmpɪtənt/', 'adjective', '{"zh-TW":["能勝任的；稱職的"],"en":["having the necessary ability or knowledge"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"pet","meaning":"seek (尋求)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"完全具備所尋求的能力，即「稱職的」。"}', 'highly competent / competent in', '[{"en":"She is a highly competent project manager.","zh-TW":"她是一位非常稱職的專案經理。"},{"en":"The candidate must be competent in data analysis.","zh-TW":"候選人必須擅長數據分析。"}]', '{"noun":"competence"}', NULL, 3, 1306, NULL),
(1307, 'competition', 'ˌkɒmpɪˈtɪʃən', 'noun', '{"zh-TW":["競爭；比賽","對手"],"en":["the activity of competing","a contest"]}', NULL, 'market competition/fair competition', '[{"en":"The competition in this industry is fierce.","zh-TW":"這個行業的競爭很激烈。"}]', '{"verb":"compete","adjective":"competitive","adverb":"competitively"}', NULL, 4, 1307, 526),
(1308, 'competitive', 'kəmˈpɛtɪtɪv', 'adjective', '{"zh-TW":["競爭性的；有競爭力的","好勝的"],"en":["involving competition","able to compete"]}', NULL, 'competitive price/competitive market', '[{"en":"We offer competitive pricing.","zh-TW":"我們提供有競爭力的定價。"}]', '{"noun":"competition","adverb":"competitively"}', NULL, 4, 1308, 296),
(1309, 'competitive advantage', '/kəmˈpetɪtɪv ədˈvɑːntɪdʒ/', 'noun', '{"zh-TW":["競爭優勢"],"en":["a condition giving a company an edge over competitors"]}', NULL, 'sustainable competitive advantage / competitive advantage over', '[{"en":"Low costs give them a competitive advantage in the market.","zh-TW":"低成本使他們在市場上具有競爭優勢。"},{"en":"Innovation is the company''s key competitive advantage.","zh-TW":"創新是公司的核心競爭優勢。"}]', '{"adjective":"competitive"}', NULL, 5, 1309, NULL),
(1310, 'competitive analysis', '/kəmˈpetɪtɪv əˈnælɪsɪs/', 'noun', '{"zh-TW":["競爭分析"],"en":["evaluating competitors'' strengths, weaknesses, and strategies"]}', NULL, 'conduct a competitive analysis / competitive analysis framework', '[{"en":"The competitive analysis revealed that the company was priced too high.","zh-TW":"競爭分析顯示公司定價過高。"},{"en":"A SWOT analysis is a common tool in competitive analysis.","zh-TW":"SWOT分析是競爭分析中的常用工具。"}]', NULL, NULL, 5, 1310, NULL),
(1311, 'competitive bidding', '/kəmˈpɛtɪtɪv ˈbɪdɪŋ/', 'noun', '{"zh-TW":["競爭性投標"],"en":["a process in which multiple parties submit bids for a contract"]}', NULL, 'competitive bidding process / open competitive bidding', '[{"en":"The contract was awarded through competitive bidding.","zh-TW":"合約通過競爭性投標授予。"},{"en":"Competitive bidding ensures fair pricing for public projects.","zh-TW":"競爭性投標確保了公共項目的公平定價。"}]', NULL, NULL, 5, 1311, NULL),
(1312, 'competitive edge', '/kəmˈpetɪtɪv edʒ/', 'noun', '{"zh-TW":["競爭優勢"],"en":["a factor that gives a company an advantage over competitors"]}', NULL, 'gain a competitive edge / maintain a competitive edge', '[{"en":"Innovation gave the company a competitive edge over rivals.","zh-TW":"創新使公司在競爭對手中獲得了競爭優勢。"},{"en":"Patent protection provided a competitive edge in the pharmaceutical market.","zh-TW":"專利保護在製藥市場提供了競爭優勢。"}]', NULL, NULL, 5, 1312, NULL),
(1313, 'competitive intelligence', '/kəmˈpetɪtɪv ɪnˈtelɪdʒəns/', 'noun', '{"zh-TW":["競爭情報"],"en":["information gathering and analysis of competitor activities and strategies"]}', NULL, 'gather competitive intelligence / competitive intelligence report', '[{"en":"Competitive intelligence helped the firm anticipate a rival''s product launch.","zh-TW":"競爭情報幫助公司預測了競爭對手的產品發佈。"},{"en":"Regular competitive intelligence reviews keep the team informed.","zh-TW":"定期的競爭情報審查使團隊保持知情。"}]', '{"abbreviation":"CI"}', NULL, 5, 1313, NULL),
(1314, 'competitive landscape', '/kəmˈpetɪtɪv ˈlændskeɪp/', 'noun', '{"zh-TW":["競爭格局"],"en":["an analysis of the competitive environment, including key players and their positioning"]}', NULL, 'map the competitive landscape / changing competitive landscape', '[{"en":"Mapping the competitive landscape revealed three key rivals.","zh-TW":"繪製競爭格局圖揭示了三個主要競爭對手。"},{"en":"The competitive landscape shifted dramatically after the new entrant arrived.","zh-TW":"新進入者到來後，競爭格局發生了巨大變化。"}]', NULL, NULL, 5, 1314, NULL),
(1315, 'competitive pressure', '/kəmˈpetɪtɪv ˈpreʃər/', 'noun', '{"zh-TW":["競爭壓力"],"en":["pressure from market competition to improve performance or reduce prices"]}', NULL, 'face competitive pressure / respond to competitive pressure', '[{"en":"Competitive pressure forced the company to reduce prices.","zh-TW":"競爭壓力迫使公司降低了價格。"},{"en":"Competitive pressure drove investment in innovation and efficiency.","zh-TW":"競爭壓力推動了對創新和效率的投資。"}]', NULL, NULL, 5, 1315, NULL),
(1316, 'competitive pricing', '/kəmˈpɛtɪtɪv ˈpraɪsɪŋ/', 'noun', '{"zh-TW":["競爭性定價"],"en":["pricing that is in line with or better than competitors"]}', NULL, 'adopt competitive pricing / competitive pricing strategy', '[{"en":"The company uses competitive pricing to attract new customers.","zh-TW":"公司採用競爭性定價來吸引新顧客。"},{"en":"Competitive pricing requires regular market analysis.","zh-TW":"競爭性定價需要定期的市場分析。"}]', NULL, NULL, 5, 1316, NULL),
(1317, 'competitive tender', '/kəmˈpetɪtɪv ˈtendər/', 'noun', '{"zh-TW":["競爭性招標"],"en":["a procurement method requiring suppliers to bid against each other"]}', NULL, 'issue a competitive tender / respond to a competitive tender', '[{"en":"The city issued a competitive tender for the road construction project.","zh-TW":"市政府為道路建設項目發出了競爭性招標。"},{"en":"All vendors were invited to submit bids through competitive tender.","zh-TW":"所有供應商受邀通過競爭性招標提交投標書。"}]', NULL, NULL, 5, 1317, NULL),
(1318, 'competitiveness', '/kəmˈpetɪtɪvnəs/', 'noun', '{"zh-TW":["競爭力"],"en":["the quality of being as good as or better than others"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pet","meaning":"seek (尋求)"},"suffix":{"text":"-iveness","meaning":"state (狀態)"},"logic":"一起尋求目標的能力狀態，即「競爭力」。"}', 'global competitiveness / enhance competitiveness / price competitiveness', '[{"en":"Innovation is key to maintaining competitiveness.","zh-TW":"創新是保持競爭力的關鍵。"},{"en":"Lower costs improve our price competitiveness.","zh-TW":"降低成本提升我們的價格競爭力。"}]', '{"adjective":"competitive","verb":"compete"}', NULL, 5, 1318, NULL),
(1319, 'competitor analysis', '/kəmˈpɛtɪtər əˈnælɪsɪs/', 'noun', '{"zh-TW":["競爭對手分析"],"en":["the study of rival companies to understand their strategies"]}', NULL, 'conduct competitor analysis / competitor analysis report', '[{"en":"Regular competitor analysis keeps the company informed.","zh-TW":"定期進行競爭對手分析使公司保持了解。"},{"en":"The marketing team prepared a competitor analysis report.","zh-TW":"行銷團隊準備了競爭對手分析報告。"}]', NULL, NULL, 5, 1319, NULL),
(1320, 'compile', '/kəmˈpaɪl/', 'verb', '{"zh-TW":["彙編；匯集","編譯；彙編","編纂；彙整"],"en":["to collect and assemble information from various sources","to convert code into machine language","to produce by assembling information"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pile","meaning":"heap (堆積)"},"logic":"一起堆積，即「彙編」。"}', 'compile a report/list/database; compile code / compile a list; compile data / compile a list / compile a report', '[{"en":"The assistant compiled the data into a report.","zh-TW":"助理將數據彙編成報告。"},{"en":"We compiled a list of potential suppliers.","zh-TW":"我們匯集了一份潛在供應商清單。"},{"en":"The code failed to compile.","zh-TW":"程式碼編譯失敗了。"},{"en":"She compiled a list of errors.","zh-TW":"她彙整了一份錯誤清單。"},{"en":"She compiled a list of potential clients.","zh-TW":"她彙整了一份潛在客戶名單。"},{"en":"The report was compiled from various sources.","zh-TW":"報告是從各種來源彙整而成。"}]', '{"noun":"compilation","noun2":"compilation"}', NULL, 3, 1320, 657),
(1321, 'compiler', '/kəmˈpaɪlər/', 'noun', '{"zh-TW":["編譯器"],"en":["a program that translates source code into machine code"]}', NULL, 'run the compiler / compiler error / JIT compiler', '[{"en":"The compiler flagged type errors before the code was executed.","zh-TW":"編譯器在代碼執行之前標記了類型錯誤。"},{"en":"A just-in-time compiler optimizes performance at runtime.","zh-TW":"即時編譯器在運行時優化性能。"}]', '{"verb":"compile","noun2":"compilation"}', NULL, 3, 1321, NULL),
(1322, 'complacent', '/''kɒmˈpleɪsənt/', 'adjective', '{"zh-TW":["自滿的；沾沾自喜的"],"en":["showing smug or uncritical satisfaction with oneself or one''s achievements"]}', NULL, 'become complacent / guard against complacency / complacent attitude', '[{"en":"Success can cause organizations to become complacent and stop innovating.","zh-TW":"成功可能導致組織變得自滿並停止創新。"},{"en":"A complacent employee who stops developing skills will quickly fall behind peers.","zh-TW":"停止發展技能的自滿員工將很快落後於同事。"}]', '{"noun":"complacency","adverb":"complacently"}', NULL, 4, 1322, NULL),
(1323, 'complain', '/kəmˈpleɪn/', 'verb', '{"zh-TW":["抱怨；投訴"],"en":["to say you are unhappy about something"]}', NULL, 'complain about / complain to', '[{"en":"She complained about the noise.","zh-TW":"她抱怨噪音。"},{"en":"Customers complained to the manager.","zh-TW":"顧客向經理投訴。"}]', '{"noun":"complaint"}', NULL, 3, 1323, NULL),
(1324, 'complaint', '/kəmˈpleɪnt/', 'noun', '{"zh-TW":["投訴；抱怨"],"en":["an expression of dissatisfaction"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"plaint","meaning":"lament (悲嘆)"},"logic":"一起發出悲嘆，即「抱怨」。"}', 'file a complaint / customer complaint', '[{"en":"We received several complaints about the noise.","zh-TW":"我們收到了幾起關於噪音的投訴。"},{"en":"She filed a complaint with the manager.","zh-TW":"她向經理提出投訴。"}]', '{"verb":"complain","noun":"complainant"}', NULL, 3, 1324, 86),
(1325, 'complaint handling', '/kəmˈpleɪnt ˈhændəlɪŋ/', 'noun', '{"zh-TW":["投訴處理"],"en":["the process of receiving and resolving customer complaints"]}', NULL, 'complaint handling process / effective complaint handling', '[{"en":"Efficient complaint handling can strengthen customer relationships.","zh-TW":"有效的投訴處理可以加強客戶關係。"},{"en":"All customer complaints must be acknowledged within 24 hours.","zh-TW":"所有客戶投訴必須在24小時內得到確認。"}]', NULL, NULL, 5, 1325, NULL),
(1326, 'complement', '/ˈkɒmplɪment/', 'verb', '{"zh-TW":["補充；相輔相成"],"en":["to add to something to enhance or improve it"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"ple","meaning":"fill (填)"},"suffix":{"text":"-ment","meaning":"thing (事物)"},"logic":"完全填滿的東西，即「補充」。"}', 'complement each other / complement skills', '[{"en":"The two departments complement each other well.","zh-TW":"兩個部門相輔相成。"},{"en":"Her skills complement those of her business partner.","zh-TW":"她的技能與商業夥伴的互補。"}]', '{"adjective":"complementary"}', NULL, 4, 1326, 527),
(1327, 'complementarity', '/ˌkɒmplɪmenˈtærɪti/', 'noun', '{"zh-TW":["互補性"],"en":["the fact of being complementary or completing each other"]}', NULL, 'economic complementarity / skill complementarity / complementarity of approaches', '[{"en":"Complementarity between public and private investment drives growth.","zh-TW":"公共和私人投資之間的互補性推動了增長。"},{"en":"The complementarity of quantitative and qualitative methods strengthens research.","zh-TW":"量化和質性方法的互補性增強了研究。"}]', '{"adjective":"complementary"}', NULL, 5, 1327, NULL),
(1328, 'complementary service', '/''kɒmplɪˌmentəri ˌsɜːrvɪs/', 'noun', '{"zh-TW":["免費服務；贈送服務"],"en":["a service provided at no extra charge, often as an additional benefit"]}', NULL, 'offer complementary services / complementary service available / enjoy complementary services', '[{"en":"The hotel offered complementary breakfast and airport shuttle to all guests.","zh-TW":"飯店為所有客人提供免費早餐和機場接送服務。"},{"en":"Complementary services such as free Wi-Fi have become standard expectations for hotel guests.","zh-TW":"免費Wi-Fi等贈送服務已成為飯店客人的標準期望。"}]', '{"adjective":"complementary"}', NULL, 5, 1328, NULL),
(1329, 'complete', '/kəmˈpliːt/', 'verb', '{"zh-TW":["完成；完整的"],"en":["to finish","having all parts"]}', NULL, 'complete a task / complete set', '[{"en":"Please complete the form by Friday.","zh-TW":"請在週五前填好表格。"},{"en":"The renovation is now complete.","zh-TW":"翻新工程已經完成了。"}]', '{"verb":"complete","adjective":"complete","noun":"completion","adverb":"completely"}', NULL, 3, 1329, 16),
(1330, 'complex', '/ˈkɒmpleks/', 'adjective', '{"zh-TW":["複雜的"],"en":["consisting of many different parts; not easy to understand"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"plex","meaning":"weave (編織)"},"logic":"編織在一起的，即「複雜的」。"}', 'complex issue/system/process', '[{"en":"International tax law is extremely complex.","zh-TW":"國際稅法極其複雜。"},{"en":"The project involves complex logistics.","zh-TW":"該專案涉及複雜的物流。"}]', '{"noun":"complexity"}', NULL, 3, 1330, NULL),
(1331, 'compliance', '/kəmˈplaɪəns/', 'noun', '{"zh-TW":["合規；遵守"],"en":["the act of conforming to a rule or standard"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"pli","meaning":"fold/fill (折疊/充滿)"},"suffix":{"text":"-ance","meaning":"state (狀態)"},"logic":"完全充滿順從的狀態，即「合規」。"}', 'regulatory compliance / in compliance with / compliance officer', '[{"en":"The company is in full compliance with all regulations.","zh-TW":"公司完全遵守所有法規。"},{"en":"A compliance officer monitors adherence to policies.","zh-TW":"合規官監督政策遵守情況。"}]', '{"verb":"comply","adjective":"compliant"}', NULL, 4, 1331, 297),
(1332, 'compliance audit', '/kəmˈplaɪəns ˈɔːdɪt/', 'noun', '{"zh-TW":["合規審計"],"en":["an independent review to verify that laws and policies are being followed"]}', NULL, 'conduct a compliance audit / compliance audit findings', '[{"en":"The annual compliance audit found no significant violations.","zh-TW":"年度合規審計未發現重大違規行為。"},{"en":"A compliance audit provides assurance to regulators and management.","zh-TW":"合規審計為監管機構和管理層提供了保證。"}]', NULL, NULL, 5, 1332, NULL),
(1333, 'compliance check', '/kəmˈplaɪəns tʃek/', 'noun', '{"zh-TW":["合規檢查"],"en":["a review or audit to ensure that an organization is following relevant laws, regulations, or policies"]}', NULL, 'conduct a compliance check / compliance check result / routine compliance check', '[{"en":"The compliance check found that all safety protocols were being followed correctly.","zh-TW":"合規檢查發現所有安全協議都在正確執行。"},{"en":"Regular compliance checks help companies identify and address regulatory issues proactively.","zh-TW":"定期的合規檢查幫助公司主動識別和解決監管問題。"}]', '{"verb":"check","noun":"compliance"}', NULL, 5, 1333, NULL),
(1334, 'compliance officer', '/kəmˈplaɪəns ˈɒfɪsər/', 'noun', '{"zh-TW":["合規主任；合規官員"],"en":["a person responsible for ensuring regulatory compliance"]}', NULL, 'appoint a compliance officer / report to the compliance officer', '[{"en":"The compliance officer reviewed all company policies for legal adherence.","zh-TW":"合規主任審查了所有公司政策的法律合規性。"},{"en":"Concerns about misconduct should be reported to the compliance officer.","zh-TW":"關於不當行為的顧慮應向合規主任報告。"}]', NULL, NULL, 5, 1334, NULL),
(1335, 'compliant', 'kəmˈplaɪənt', 'adjective', '{"zh-TW":["合規的；遵從的","符合規定的"],"en":["meeting required standards","following rules"]}', NULL, 'tax compliant/regulatory compliant', '[{"en":"All products must be fully compliant.","zh-TW":"所有產品必須完全合規。"}]', '{"verb":"comply","noun":"compliance","adverb":"compliantly"}', NULL, 3, 1335, NULL),
(1336, 'complicate', '/ˈkɒmplɪkeɪt/', 'verb', '{"zh-TW":["使複雜化"],"en":["to make something more difficult or complex"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"plic","meaning":"fold (折疊)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使東西摺疊在一起，即「使複雜」。"}', 'complicate matters / further complicate', '[{"en":"His arrival only complicated matters.","zh-TW":"他的到來只是讓事情更複雜。"},{"en":"Don''t complicate things unnecessarily.","zh-TW":"不要把事情不必要地複雜化。"}]', '{"noun":"complication","adjective":"complicated"}', NULL, 4, 1336, NULL),
(1337, 'complication', '/ˌkɒmplɪˈkeɪʃən/', 'noun', '{"zh-TW":["併發症；複雜化"],"en":["a secondary medical condition or an unforeseen difficulty"]}', NULL, 'develop a complication / postoperative complication / manage complications', '[{"en":"The patient developed a complication requiring an additional procedure.","zh-TW":"患者出現了需要額外手術的併發症。"},{"en":"Diabetes increases the risk of cardiovascular complications.","zh-TW":"糖尿病增加了心血管併發症的風險。"}]', '{"verb":"complicate","adjective":"complicated"}', NULL, 4, 1337, NULL),
(1338, 'complicity', '/''kɒmˈplɪsɪti/', 'noun', '{"zh-TW":["共謀；同謀"],"en":["the fact or condition of being involved with others in an activity that is unlawful or morally wrong"]}', NULL, 'allegation of complicity / deny complicity / corporate complicity', '[{"en":"Investigators found evidence of complicity among several senior executives.","zh-TW":"調查人員發現了幾位高級管理人員共謀的證據。"},{"en":"The organization denied any complicity in the financial irregularities.","zh-TW":"該組織否認在財務違規中有任何共謀。"}]', '{"adjective":"complicit"}', NULL, 4, 1338, NULL),
(1339, 'complimentary', '/ˌkɒmplɪˈmɛntəri/', 'adjective', '{"zh-TW":["免費的；贈送的"],"en":["given free of charge"]}', NULL, 'complimentary breakfast / complimentary service', '[{"en":"The hotel offers a complimentary breakfast for guests.","zh-TW":"飯店為住客提供免費早餐。"},{"en":"Complimentary wifi is available in all rooms.","zh-TW":"所有房間均提供免費無線網路。"}]', NULL, NULL, 5, 1339, NULL),
(1340, 'complimentary upgrade', '/ˌkɒmplɪˈmɛntəri ˈʌpɡreɪd/', 'noun', '{"zh-TW":["免費升等"],"en":["a free improvement to a better class or seat"]}', NULL, 'receive a complimentary upgrade / offer a complimentary upgrade', '[{"en":"She received a complimentary upgrade to business class.","zh-TW":"她獲得了免費升等至商務艙。"},{"en":"Frequent flyers are often given complimentary upgrades.","zh-TW":"常旅客通常獲得免費升等。"}]', NULL, NULL, 5, 1340, NULL),
(1341, 'comply', '/kəmˈplaɪ/', 'verb', '{"zh-TW":["遵守；符合"],"en":["to act in accordance with a rule or request"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"ply","meaning":"fold/fill (折疊/充滿)"},"logic":"完全充滿順從，即「遵守」。"}', 'comply with regulations/standards/requirements', '[{"en":"All products must comply with safety standards.","zh-TW":"所有產品必須符合安全標準。"},{"en":"Failure to comply may result in penalties.","zh-TW":"不遵守可能導致罰款。"}]', '{"noun":"compliance","adjective":"compliant"}', NULL, 2, 1341, 87),
(1342, 'comply with regulations', '/kəmˈplaɪ wɪð ˌreɡjʊˈleɪʃənz/', 'verb', '{"zh-TW":["遵守法規"],"en":["to follow all applicable rules and government requirements"]}', NULL, 'comply with regulations / ensure compliance with regulations', '[{"en":"All products must comply with safety regulations before sale.","zh-TW":"所有產品在銷售前必須遵守安全法規。"},{"en":"The factory was fined for failing to comply with environmental regulations.","zh-TW":"工廠因未能遵守環境法規而被罰款。"}]', NULL, NULL, 5, 1342, NULL),
(1343, 'component', '/kəmˈpəʊnənt/', 'noun', '{"zh-TW":["組件；成分"],"en":["a part or element of a larger whole"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pon","meaning":"put (放置)"},"suffix":{"text":"-ent","meaning":"thing (事物)"},"logic":"放置在一起的東西，即「組件」。"}', 'key component / component parts / electronic component', '[{"en":"Quality control is a key component of manufacturing.","zh-TW":"品質控制是製造業的關鍵組成部分。"},{"en":"The device contains over 500 electronic components.","zh-TW":"該裝置包含超過500個電子元件。"}]', NULL, NULL, 3, 1343, 298),
(1344, 'compose', '/kəmˈpəʊz/', 'verb', '{"zh-TW":["組成；撰寫","作曲；組成"],"en":["to make up the whole","to write or create","to write music","to make up or form something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pose","meaning":"put/place (放置)"},"logic":"一起放置，即「組成」。"}', 'be composed of / compose a letter; compose a symphony / compose oneself', '[{"en":"The committee is composed of 12 members.","zh-TW":"委員會由12名成員組成。"},{"en":"She composed a formal response to the complaint.","zh-TW":"她撰寫了對投訴的正式回覆。"},{"en":"Beethoven composed nine symphonies.","zh-TW":"貝多芬創作了九首交響曲。"}]', '{"noun":"composition","noun2":"composition"}', NULL, 3, 1344, NULL),
(1345, 'compost', '/ˈkɒmpɒst/', 'noun', '{"zh-TW":["堆肥"],"en":["decayed organic matter used as fertilizer"]}', NULL, 'make compost / compost bin', '[{"en":"Food scraps can be turned into compost for the garden.","zh-TW":"廚餘可以製成花園用的堆肥。"},{"en":"The restaurant donates food waste to a composting program.","zh-TW":"餐廳將廚餘捐給堆肥計劃。"}]', '{"verb":"compost","adjective":"composted"}', NULL, 3, 1345, NULL),
(1346, 'composting', '/ˈkɒmpɒstɪŋ/', 'noun', '{"zh-TW":["堆肥；有機廢棄物堆肥化"],"en":["the process of recycling organic matter into fertilizer for soil"]}', NULL, 'practice composting / composting program / industrial composting', '[{"en":"Composting diverts food waste from landfills and enriches soil.","zh-TW":"堆肥將食物廚餘從填埋場轉移並豐富土壤。"},{"en":"Schools use composting programs to teach students about sustainability.","zh-TW":"學校使用堆肥計畫向學生教授永續性知識。"}]', '{"verb":"compost","adjective":"composted"}', NULL, 4, 1346, NULL),
(1347, 'compound', '/''kɒmpaʊnd/', 'verb', '{"zh-TW":["加重；使複雜化"],"en":["to make a problem, condition, or emotion worse or more intense"]}', NULL, 'compound a problem / compound an error / compound interest', '[{"en":"The lack of sleep compounded her anxiety about the upcoming exam.","zh-TW":"睡眠不足加重了她對即將到來的考試的焦慮。"},{"en":"Poor communication can compound misunderstandings and cause further conflict.","zh-TW":"溝通不暢可能加重誤解並引發進一步衝突。"}]', '{"noun":"compound","adjective":"compound"}', NULL, 3, 1347, NULL),
(1348, 'compound growth', '/ˈkɒmpaʊnd ɡroʊθ/', 'noun', '{"zh-TW":["複合增長"],"en":["growth calculated on the initial amount plus accumulated gains over time"]}', NULL, 'achieve compound growth / compound growth rate', '[{"en":"The investment achieved compound growth of 8% annually over 10 years.","zh-TW":"該投資在10年內實現了每年8%的複合增長。"},{"en":"Compound growth makes long-term investing significantly more rewarding.","zh-TW":"複合增長使長期投資更具顯著回報。"}]', '{"adjective":"compound"}', NULL, 5, 1348, NULL),
(1349, 'compound interest', '/ˈkɒmpaʊnd ˈɪntrəst/', 'noun', '{"zh-TW":["複利"],"en":["interest calculated on both the principal and accumulated interest"]}', NULL, 'earn compound interest / calculate compound interest / effect of compound interest', '[{"en":"Compound interest makes savings grow exponentially over time.","zh-TW":"複利使儲蓄隨時間呈指數增長。"},{"en":"The effect of compound interest is most powerful over long periods.","zh-TW":"複利的效應在長期內最為強大。"}]', '{"adjective":"compound","antonym":"simple interest"}', NULL, 5, 1349, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1350, 'comprehensive', '/ˌkɒmprɪˈhensɪv/', 'adjective', '{"zh-TW":["全面的；綜合的"],"en":["including all or nearly all aspects of something"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"prehens","meaning":"grasp (抓住)"},"suffix":{"text":"-ive","meaning":"having quality (具有特質)"},"logic":"完全抓住所有面向的，即「全面的」。"}', 'comprehensive plan/review/report', '[{"en":"We conducted a comprehensive review of all policies.","zh-TW":"我們對所有政策進行了全面審查。"},{"en":"The package includes comprehensive health insurance.","zh-TW":"該方案包括全面的健康保險。"}]', '{"adverb":"comprehensively"}', NULL, 5, 1350, 299),
(1351, 'comprehensive insurance', '/ˌkɒmprɪˈhensɪv ɪnˈʃʊərəns/', 'noun', '{"zh-TW":["綜合保險"],"en":["insurance coverage that protects against a wide range of risks"]}', NULL, 'obtain comprehensive insurance / comprehensive insurance policy', '[{"en":"The company holds comprehensive insurance covering property, liability, and business interruption.","zh-TW":"公司持有涵蓋財產、責任和業務中斷的綜合保險。"},{"en":"Comprehensive insurance premiums are higher but provide broader protection.","zh-TW":"綜合保險費用較高，但提供更廣泛的保障。"}]', '{"opposite":"third-party insurance"}', NULL, 5, 1351, NULL),
(1352, 'comprise', '/kəmˈpraɪz/', 'verb', '{"zh-TW":["包含；由…組成"],"en":["to consist of; to be made up of"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"prise","meaning":"take (拿取)"},"logic":"一起拿取在內，即「包含」。"}', 'comprise of / be comprised of', '[{"en":"The team comprises specialists from various departments.","zh-TW":"團隊由各部門的專家組成。"},{"en":"Women comprise 45% of the workforce.","zh-TW":"女性占勞動力的45%。"}]', NULL, NULL, 3, 1352, NULL),
(1353, 'compromise', '/ˈkɒmprəmaɪz/', 'noun', '{"zh-TW":["妥協；折衷"],"en":["an agreement reached by each side giving up something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"promise","meaning":"promise (承諾)"},"logic":"一起做出讓步承諾，即「妥協」。"}', 'reach a compromise / make a compromise', '[{"en":"Both sides reached a compromise on the pricing.","zh-TW":"雙方在定價上達成了妥協。"},{"en":"Quality should never be compromised for speed.","zh-TW":"不應為了速度而犧牲品質。"}]', NULL, NULL, 4, 1353, NULL),
(1354, 'compulsory', '/kəmˈpʌlsəri/', 'adjective', '{"zh-TW":["強制的；義務的","強制的；必修的"],"en":["required by law or rule; obligatory","required by law or rule"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"puls","meaning":"drive (驅使)"},"suffix":{"text":"-ory","meaning":"relating to (有關的)"},"logic":"完全被驅使的，即「強制的」。"}', 'compulsory training/education/insurance; compulsory education / compulsory subject', '[{"en":"Attendance at the safety training is compulsory.","zh-TW":"安全訓練的出席是強制性的。"},{"en":"The company has compulsory retirement at age 65.","zh-TW":"公司規定65歲強制退休。"},{"en":"Education is compulsory until age 16.","zh-TW":"教育在16歲前是義務的。"},{"en":"Math is a compulsory subject.","zh-TW":"數學是必修科目。"}]', '{"verb":"compel"}', NULL, 4, 1354, NULL),
(1355, 'compulsory purchase', '/kəmˈpʌlsəri ˈpɜːrtʃɪs/', 'noun', '{"zh-TW":["強制購買；強制收購"],"en":["the government''s legal right to acquire private property for public use"]}', NULL, 'subject to compulsory purchase / compulsory purchase order', '[{"en":"The property was acquired through a compulsory purchase for road construction.","zh-TW":"房產通過強制購買用於道路建設。"},{"en":"Compensation must be paid at market value in a compulsory purchase.","zh-TW":"強制購買必須按市場價值支付賠償。"}]', '{"synonym":"eminent domain"}', NULL, 5, 1355, NULL),
(1356, 'compulsory redundancy', '/kəmˈpʌlsəri rɪˈdʌndənsi/', 'noun', '{"zh-TW":["強制裁員"],"en":["job losses where employees are dismissed against their will due to business needs"]}', NULL, 'avoid compulsory redundancy / compulsory redundancy process', '[{"en":"The company tried to avoid compulsory redundancy through redeployment.","zh-TW":"公司試圖通過內部調配避免強制裁員。"},{"en":"Compulsory redundancy must follow legal notice and consultation requirements.","zh-TW":"強制裁員必須遵守法定通知和諮詢要求。"}]', NULL, NULL, 5, 1356, NULL),
(1357, 'computational biology', '/ˌkɒmpjʊˈteɪʃənəl baɪˈɒlədʒi/', 'noun', '{"zh-TW":["計算生物學"],"en":["the use of computational methods to analyze biological systems"]}', NULL, 'apply computational biology / computational biology tools / advance computational biology', '[{"en":"Computational biology accelerates the discovery of new drugs.","zh-TW":"計算生物學加速了新藥的發現。"},{"en":"Genome sequencing would be impossible without computational biology.","zh-TW":"沒有計算生物學，基因組測序將是不可能的。"}]', '{"adjective":"computational biologist"}', NULL, 5, 1357, NULL),
(1358, 'computationally', '/kəmˌpjuːtəˈʃənəli/', 'adverb', '{"zh-TW":["計算上；在計算方面"],"en":["in terms of what is possible with computers"]}', NULL, 'computationally expensive / computationally intensive / computationally efficient', '[{"en":"Some optimization problems are computationally intractable without heuristics.","zh-TW":"一些優化問題在沒有啟發法的情況下在計算上難以解決。"},{"en":"The algorithm is computationally efficient even on large datasets.","zh-TW":"該算法即使在大型數據集上也具有計算效率。"}]', '{"adjective":"computational"}', NULL, 5, 1358, NULL),
(1359, 'computer', '/kəmˈpjuːtər/', 'noun', '{"zh-TW":["電腦"],"en":["an electronic device for processing data"]}', NULL, 'computer system / computer skills', '[{"en":"All employees need basic computer skills.","zh-TW":"所有員工都需要基本的電腦技能。"},{"en":"The computer system crashed this morning.","zh-TW":"電腦系統今早當機了。"}]', '{"noun":"computer","verb":"compute","noun2":"computation"}', NULL, 3, 1359, NULL),
(1360, 'conceal', '/kənˈsiːl/', 'verb', '{"zh-TW":["隱藏；隱瞞"],"en":["to keep from sight; to hide"]}', '{"prefix":{"text":"con-","meaning":"completely (完全)"},"root":{"text":"ceal","meaning":"hide (藏)"},"logic":"完全藏起來，即「隱藏」。"}', 'conceal information/facts/identity', '[{"en":"The report accused the firm of concealing financial losses.","zh-TW":"報告指控該公司隱瞞財務虧損。"},{"en":"It is illegal to conceal material information from investors.","zh-TW":"向投資者隱瞞重要資訊是違法的。"}]', '{"noun":"concealment"}', NULL, 3, 1360, NULL),
(1361, 'concealment', '/kənˈsiːlmənt/', 'noun', '{"zh-TW":["隱瞞；隱藏"],"en":["the deliberate withholding of material information from another party"]}', NULL, 'material concealment / concealment of facts', '[{"en":"Concealment of a known defect may invalidate the insurance policy.","zh-TW":"隱瞞已知缺陷可能使保險單失效。"},{"en":"The auditors discovered the concealment of liabilities in the accounts.","zh-TW":"審計師在帳目中發現了對負債的隱瞞。"}]', '{"verb":"conceal"}', NULL, 4, 1361, NULL),
(1362, 'concentrate', '/ˈkɒnsntreɪt/', 'verb', '{"zh-TW":["集中；專注"],"en":["to focus attention or effort on something","to focus all attention on something"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"centr","meaning":"center (中心)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使聚集到中心，即「集中」。"}', 'concentrate on / concentrate efforts; concentrate on / unable to concentrate', '[{"en":"We should concentrate our efforts on core business.","zh-TW":"我們應該將精力集中在核心業務上。"},{"en":"The company decided to concentrate on the domestic market.","zh-TW":"公司決定專注於國內市場。"},{"en":"I need to concentrate on my work.","zh-TW":"我需要專注在工作上。"},{"en":"She couldn''t concentrate because of the noise.","zh-TW":"因為噪音她無法集中精神。"}]', '{"noun":"concentration"}', NULL, 4, 1362, 731),
(1363, 'concentration risk', '/ˌkɒnsənˈtreɪʃən rɪsk/', 'noun', '{"zh-TW":["集中風險"],"en":["the risk from having too high a dependency on a single customer or supplier"]}', NULL, 'manage concentration risk / high concentration risk', '[{"en":"The company reduced concentration risk by diversifying its supplier base.","zh-TW":"公司通過多元化供應商基礎降低了集中風險。"},{"en":"Concentration risk is high when 50% of revenue comes from one client.","zh-TW":"當50%的收入來自一個客戶時，集中風險很高。"}]', NULL, NULL, 5, 1363, NULL),
(1364, 'concept', '/ˈkɒnsept/', 'noun', '{"zh-TW":["概念；構想","概念"],"en":["an abstract idea or general notion"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"cept","meaning":"take/seize (抓取)"},"logic":"完全抓住的想法，即「概念」。"}', 'concept of / new concept / concept design; basic concept / new concept / concept of', '[{"en":"The concept of remote work has gained widespread acceptance.","zh-TW":"遠端工作的概念已獲得廣泛接受。"},{"en":"The team presented a new product concept.","zh-TW":"團隊展示了一個新的產品概念。"},{"en":"The concept is simple but effective.","zh-TW":"概念簡單但有效。"},{"en":"He introduced a new concept in design.","zh-TW":"他引入了一個新的設計概念。"}]', '{"adjective":"conceptual"}', NULL, 3, 1364, 300),
(1365, 'conceptualization', '/kənˌseptʃuəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["概念化；概念形成"],"en":["the process of forming a concept or idea"]}', NULL, 'conceptualization of a problem / theoretical conceptualization / improve conceptualization', '[{"en":"The conceptualization of the research question determines the study design.","zh-TW":"研究問題的概念化決定了研究設計。"},{"en":"Clear conceptualization prevents confusion between related but distinct concepts.","zh-TW":"清晰的概念化防止相關但不同概念之間的混淆。"}]', '{"verb":"conceptualize","adjective":"conceptualized"}', NULL, 5, 1365, NULL),
(1366, 'concern', '/kənˈsɜːrn/', 'noun', '{"zh-TW":["關注；擔憂","事業","擔心；關切"],"en":["a matter of interest or importance","worry or anxiety","worry; something that causes anxiety"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"cern","meaning":"sift/separate (篩選)"},"logic":"完全篩選注意的事，即「關注」。"}', 'raise concerns / major concern / concern about; major concern / express concern / growing concern', '[{"en":"Safety is our primary concern.","zh-TW":"安全是我們首要關注的事項。"},{"en":"Several employees raised concerns about the policy.","zh-TW":"幾位員工對該政策提出了擔憂。"},{"en":"Safety is our primary concern.","zh-TW":"安全是我們最主要的關切。"},{"en":"There is growing concern about climate change.","zh-TW":"對氣候變遷的擔憂日益增加。"}]', '{"adjective":"concerned","verb":"concern","adjective2":"concerning"}', NULL, 3, 1366, 88),
(1367, 'concerned', 'kənˈsɜːrnd', 'adjective', '{"zh-TW":["擔憂的；關切的","相關的"],"en":["worried about something","involved in something"]}', NULL, 'be concerned about/parties concerned', '[{"en":"Management is concerned about the results.","zh-TW":"管理層對結果感到擔憂。"}]', '{"verb":"concern","noun":"concern","adverb":"concernedly"}', NULL, 3, 1367, NULL),
(1368, 'concert', '/ˈkɒnsərt/', 'noun', '{"zh-TW":["音樂會；演唱會"],"en":["a public musical performance"]}', NULL, 'concert hall / rock concert', '[{"en":"We went to a concert last night.","zh-TW":"我們昨晚去了演唱會。"},{"en":"The concert was sold out.","zh-TW":"演唱會門票售罄了。"}]', NULL, NULL, 3, 1368, NULL),
(1369, 'concession', '/kənˈsɛʃən/', 'noun', '{"zh-TW":["讓步；特許；優惠"],"en":["something granted as a compromise"]}', NULL, 'make a concession / price concession', '[{"en":"Both parties made concessions to reach the agreement.","zh-TW":"雙方做出了讓步以達成協議。"},{"en":"The company offered a price concession to secure the contract.","zh-TW":"公司提供了價格優惠以確保合約。"}]', '{"verb":"concede","adjective":"concessionary"}', NULL, 4, 1369, NULL),
(1370, 'concierge', '/ˌkɒnsiˈɛərʒ/', 'noun', '{"zh-TW":["禮賓人員"],"en":["a hotel employee who assists guests with services"]}', NULL, 'hotel concierge / ask the concierge', '[{"en":"The concierge recommended a nearby restaurant.","zh-TW":"禮賓員推薦了附近的餐廳。"},{"en":"Ask the concierge to arrange a taxi for you.","zh-TW":"請禮賓員幫您叫計程車。"}]', NULL, NULL, 3, 1370, NULL),
(1371, 'concierge desk', '/''kɒnsiˈerʒ desk/', 'noun', '{"zh-TW":["禮賓服務台"],"en":["a hotel front desk staffed by concierge personnel who assist guests with various needs"]}', NULL, 'ask at the concierge desk / visit the concierge desk / concierge desk recommendation', '[{"en":"She asked at the concierge desk for restaurant recommendations.","zh-TW":"她在禮賓服務台詢問餐廳推薦。"},{"en":"The concierge desk can arrange tours, transportation, and event tickets.","zh-TW":"禮賓服務台可以安排旅遊、交通和活動門票。"}]', NULL, NULL, 5, 1371, NULL),
(1372, 'conciliatory', '/''kənˌsɪliəˌtɔːri/', 'adjective', '{"zh-TW":["調解的；和解的"],"en":["intended or likely to placate or reconcile; showing a willingness to resolve a dispute"]}', NULL, 'conciliatory gesture / conciliatory tone / conciliatory approach', '[{"en":"He adopted a conciliatory tone in the meeting to ease tensions between the two sides.","zh-TW":"他在會議中採取了調解的語氣，以緩和雙方之間的緊張關係。"},{"en":"Her conciliatory gesture of offering a compromise helped break the deadlock.","zh-TW":"她提出妥協的調解姿態幫助打破了僵局。"}]', '{"adverb":"conciliatorily","verb":"conciliate","noun":"conciliation"}', NULL, 4, 1372, NULL),
(1373, 'concise', 'kənˈsaɪs', 'adjective', '{"zh-TW":["簡潔的；簡明的","扼要的"],"en":["expressing much in few words","brief but clear"]}', NULL, 'concise report/concise summary', '[{"en":"Please write a concise summary.","zh-TW":"請寫一個簡明的摘要。"}]', '{"noun":"conciseness","adverb":"concisely"}', NULL, 3, 1373, 843),
(1374, 'conclude', '/kənˈkluːd/', 'verb', '{"zh-TW":["結論；結束","總結；結束"],"en":["to bring to an end","to arrive at a judgment or opinion","to arrive at a judgment"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"clude","meaning":"close (關閉)"},"logic":"完全關閉，即「結束、下結論」。"}', 'conclude that / conclude a deal/meeting; conclude a meeting / conclude that', '[{"en":"The study concluded that the treatment was effective.","zh-TW":"研究得出結論認為該治療有效。"},{"en":"Negotiations were concluded successfully.","zh-TW":"談判成功結束。"},{"en":"The meeting concluded at 5 p.m.","zh-TW":"會議在下午五點結束。"},{"en":"The study concluded that exercise improves mental health.","zh-TW":"研究總結運動能改善心理健康。"}]', '{"noun":"conclusion","adjective":"conclusive"}', NULL, 3, 1374, NULL),
(1375, 'conclusion', 'kənˈkluːʒən', 'noun', '{"zh-TW":["結論；結尾","結果"],"en":["a judgment reached by reasoning","the end of something"]}', NULL, 'draw a conclusion/in conclusion', '[{"en":"In conclusion, the project was successful.","zh-TW":"總之，這個專案是成功的。"}]', '{"verb":"conclude","adjective":"conclusive","adverb":"conclusively"}', NULL, 4, 1375, 301),
(1376, 'concrete', '/ˈkɒŋkriːt/', 'adjective', '{"zh-TW":["具體的；確切的"],"en":["existing in a material form; specific and definite"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"crete","meaning":"grow (生長)"},"logic":"一起生長凝固的，即「具體的」。"}', 'concrete evidence/plan/example', '[{"en":"Do you have any concrete evidence to support your claim?","zh-TW":"你有任何具體證據支持你的說法嗎？"},{"en":"We need a concrete plan, not just ideas.","zh-TW":"我們需要具體計畫，而不只是想法。"}]', NULL, NULL, 3, 1376, 961),
(1377, 'concurrency', '/kənˈkɜːrənsi/', 'noun', '{"zh-TW":["並發性；同時發生"],"en":["the ability of a system to handle multiple tasks at the same time"]}', NULL, 'manage concurrency / concurrency control / high concurrency', '[{"en":"Concurrency in programming allows multiple processes to run simultaneously.","zh-TW":"程式設計中的並發性允許多個進程同時運行。"},{"en":"The database uses locking mechanisms to manage concurrency issues.","zh-TW":"資料庫使用鎖定機制來管理並發性問題。"}]', '{"adjective":"concurrent","adverb":"concurrently"}', NULL, 4, 1377, NULL),
(1378, 'concurrent liability', '/kənˈkɜːrənt ˌlaɪəˈbɪlɪti/', 'noun', '{"zh-TW":["連帶責任；共同責任"],"en":["a shared legal responsibility among multiple parties for the same event"]}', NULL, 'establish concurrent liability / concurrent liability dispute', '[{"en":"Both the contractor and subcontractor bore concurrent liability for the damage.","zh-TW":"承包商和分包商對損失承擔連帶責任。"},{"en":"Concurrent liability issues arise when multiple defendants cause the same harm.","zh-TW":"多名被告造成相同損害時會出現連帶責任問題。"}]', NULL, NULL, 5, 1378, NULL),
(1379, 'concurrently', '/''kɒnˈkɜːrəntli/', 'adverb', '{"zh-TW":["同時地；並行地"],"en":["at the same time; simultaneously"]}', NULL, 'run concurrently / operate concurrently / complete tasks concurrently', '[{"en":"The two projects were running concurrently, which required careful resource management.","zh-TW":"兩個項目同時進行，這需要仔細的資源管理。"},{"en":"She managed three client accounts concurrently without any decline in service quality.","zh-TW":"她同時管理三個客戶帳戶，服務質量沒有任何下降。"}]', '{"adjective":"concurrent"}', NULL, 4, 1379, NULL),
(1380, 'condemnation', '/ˌkɒndəmˈneɪʃən/', 'noun', '{"zh-TW":["譴責；強制徵收；定罪"],"en":["strong public criticism; the legal seizure of private property for public use"]}', NULL, 'official condemnation / condemnation of human rights abuses / property condemnation', '[{"en":"International condemnation followed the government''s crackdown on peaceful protests.","zh-TW":"在政府鎮壓和平抗議後，國際社會發出了譴責。"},{"en":"Condemnation proceedings allowed the city to acquire private land for the transit project.","zh-TW":"強制徵收程序允許市政府為交通項目收購私人土地。"}]', '{"verb":"condemn","adjective":"condemned"}', NULL, 4, 1380, NULL),
(1381, 'condiment', '/ˈkɒndɪmənt/', 'noun', '{"zh-TW":["調味料；佐料"],"en":["a sauce or seasoning added to food"]}', NULL, 'table condiment / common condiment', '[{"en":"Salt, pepper, and ketchup are common table condiments.","zh-TW":"鹽、胡椒和番茄醬是常見的餐桌調味料。"},{"en":"The restaurant provides a variety of condiments.","zh-TW":"餐廳提供各種調味料。"}]', NULL, NULL, 3, 1381, NULL),
(1382, 'condition', '/kənˈdɪʃn/', 'noun', '{"zh-TW":["條件；狀況"],"en":["the state of something","a stipulation or requirement"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"dit","meaning":"say (說)"},"suffix":{"text":"-ion","meaning":"action (動作)"},"logic":"完全說明的事，即「條件」。"}', 'working conditions / on condition that / terms and conditions', '[{"en":"The equipment is in excellent condition.","zh-TW":"設備狀況良好。"},{"en":"Please read the terms and conditions carefully.","zh-TW":"請仔細閱讀條款和條件。"}]', '{"adjective":"conditional"}', NULL, 3, 1382, 302),
(1383, 'conditional offer', '/kənˈdɪʃənəl ˈɒfər/', 'noun', '{"zh-TW":["有條件要約；有條件錄取"],"en":["an offer that is contingent upon meeting specific requirements"]}', NULL, 'make a conditional offer / accept a conditional offer', '[{"en":"A conditional offer of employment was made pending reference checks.","zh-TW":"在等待背景調查期間，提出了有條件的聘用要約。"},{"en":"The bank made a conditional offer subject to satisfactory valuation.","zh-TW":"銀行在令人滿意的估值前提下提出了有條件的要約。"}]', NULL, NULL, 5, 1383, NULL),
(1384, 'conditioning', '/''kənˈdɪʃənɪŋ/', 'noun', '{"zh-TW":["體能訓練；身體調節"],"en":["physical training that improves fitness, strength, and overall athletic performance"]}', NULL, 'physical conditioning / sports conditioning / pre-season conditioning', '[{"en":"Off-season conditioning prepares athletes for the rigors of the competitive season.","zh-TW":"賽季外的體能訓練為運動員應對競賽賽季的嚴格要求做好準備。"},{"en":"The coach designed a conditioning program to improve speed and power.","zh-TW":"教練設計了一個體能訓練計畫以提高速度和爆發力。"}]', '{"verb":"condition"}', NULL, 4, 1384, NULL),
(1385, 'condominium', '/ˌkɒndəˈmɪniəm/', 'noun', '{"zh-TW":["分層公寓；共管式公寓"],"en":["a building where units are individually owned"]}', NULL, 'buy a condominium / condominium complex', '[{"en":"She purchased a condominium in the downtown area.","zh-TW":"她在市中心購買了一棟共管式公寓。"},{"en":"The condominium complex includes a rooftop terrace.","zh-TW":"共管式公寓大廈設有屋頂露台。"}]', '{"abbreviation":"condo"}', NULL, 4, 1385, NULL),
(1386, 'conducive', '/''kɒnˈdjuːsɪv/', 'adjective', '{"zh-TW":["有助於的；有益的"],"en":["making a certain situation or outcome likely or possible; providing the right conditions"]}', NULL, 'conducive environment / conducive to learning / conducive conditions', '[{"en":"A quiet, organized workspace is conducive to deep concentration and productivity.","zh-TW":"安靜、整潔的工作空間有助於深度集中和生產力。"},{"en":"The company created a culture conducive to innovation and creative thinking.","zh-TW":"公司創建了一種有助於創新和創造性思維的文化。"}]', NULL, NULL, 3, 1386, NULL),
(1387, 'conduct', '/kənˈdʌkt/', 'verb', '{"zh-TW":["【主要意義-名詞】行為；品行","【次要意義-動詞】執行；實施（研究/調查）","【次要意義-動詞】指揮（樂團）"],"en":["[primary - noun] the way someone behaves","[secondary - verb] to carry out or manage an activity","[secondary - verb] to direct an orchestra or choir"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"duct","meaning":"lead (引導)"},"logic":"一起引導進行，即「執行」。"}', 'conduct a survey / conduct research / conduct an interview / code of conduct', '[{"en":"The company conducted a thorough review of its supply chain practices.","zh-TW":"公司對其供應鏈做法進行了全面審查。"},{"en":"All employees are expected to conduct themselves professionally.","zh-TW":"所有員工在任何時候都應以專業態度行事。"},{"en":"The HR department will conduct performance reviews next month.","zh-TW":"人力資源部下個月將進行績效評估。"}]', '{"noun":"conductor, conduction","adjective":"conductive"}', '動詞 conduct（重音在第二音節）意為「執行/實施」，句型 conduct + survey/research/interview/review 是 TOEIC 高頻搭配，與名詞 conduct（行為）重音不同。', 3, 1387, 89),
(1388, 'conduct a survey', '/kənˈdʌkt ə ˈsɜːrveɪ/', 'verb', '{"zh-TW":["進行調查"],"en":["to carry out a formal study gathering responses from participants"]}', NULL, 'conduct a customer survey / conduct an employee survey', '[{"en":"The HR team conducted a survey on workplace satisfaction.","zh-TW":"人力資源團隊對工作場所滿意度進行了調查。"},{"en":"Market research was conducted via an online survey.","zh-TW":"市場研究通過線上調查進行。"}]', NULL, NULL, 5, 1388, NULL),
(1389, 'conductor', '/kənˈdʌktər/', 'noun', '{"zh-TW":["指揮；導體"],"en":["a person who directs an orchestra","a substance that transmits heat or electricity"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"duct","meaning":"lead (引導)"},"suffix":{"text":"-or","meaning":"person who (…的人)"},"logic":"引導大家在一起的人，即「指揮」。"}', 'orchestra conductor / electrical conductor', '[{"en":"The conductor raised his baton.","zh-TW":"指揮舉起了指揮棒。"},{"en":"Copper is an excellent conductor of electricity.","zh-TW":"銅是優良的電導體。"}]', '{"verb":"conduct","noun":"conduction"}', NULL, 3, 1389, NULL),
(1390, 'conduit', '/ˈkɒndjuɪt/', 'noun', '{"zh-TW":["導管；渠道；中間人"],"en":["a channel or intermediary through which resources or information pass"]}', NULL, 'serve as a conduit / conduit for funds', '[{"en":"The subsidiary served as a conduit for transferring dividends to the parent.","zh-TW":"子公司充當了向母公司轉移股息的渠道。"},{"en":"The trade association acts as a conduit for industry feedback to regulators.","zh-TW":"行業協會充當行業向監管機構反饋的渠道。"}]', NULL, NULL, 3, 1390, 844),
(1391, 'confer', '/kənˈfɜːr/', 'verb', '{"zh-TW":["商議；授予"],"en":["to discuss something with someone","to grant or bestow"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"fer","meaning":"carry/bring (帶來)"},"logic":"一起帶來討論，即「商議」。"}', 'confer with / confer a degree/title', '[{"en":"I need to confer with my colleagues before deciding.","zh-TW":"我需要與同事商議後再決定。"},{"en":"The university conferred an honorary degree on her.","zh-TW":"大學授予她榮譽學位。"}]', '{"noun":"conference"}', NULL, 2, 1391, NULL),
(1392, 'conference call', '/ˈkɒnfərəns kɔːl/', 'noun', '{"zh-TW":["電話會議"],"en":["a telephone meeting involving multiple participants in different locations"]}', NULL, 'join a conference call / host a conference call / conference call agenda', '[{"en":"The weekly conference call aligns teams across three time zones.","zh-TW":"每週電話會議協調三個時區的團隊。"},{"en":"The conference call was recorded for those who could not attend.","zh-TW":"電話會議被錄製下來供無法出席者收聽。"}]', NULL, NULL, 5, 1392, NULL),
(1393, 'conference center', '/ˈkɒnfərəns ˈsɛntər/', 'noun', '{"zh-TW":["會議中心"],"en":["a building specifically designed for hosting conferences"]}', NULL, 'book a conference center / conference center facilities', '[{"en":"The conference center has state-of-the-art audio-visual equipment.","zh-TW":"會議中心配備了最先進的視聽設備。"},{"en":"The annual summit will be held at the downtown conference center.","zh-TW":"年度峰會將在市中心的會議中心舉行。"}]', NULL, NULL, 5, 1393, NULL),
(1394, 'confidence', '/ˈkɒnfɪdəns/', 'noun', '{"zh-TW":["信心；信任"],"en":["the feeling of being certain","trust in someone or something"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"fid","meaning":"trust (信任)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"完全信任的狀態，即「信心」。"}', 'consumer confidence / have confidence in / boost confidence', '[{"en":"Consumer confidence has risen for the third consecutive month.","zh-TW":"消費者信心連續第三個月上升。"},{"en":"I have full confidence in the team''s ability.","zh-TW":"我對團隊的能力充滿信心。"}]', '{"adjective":"confident","adverb":"confidently"}', NULL, 4, 1394, NULL),
(1395, 'confidence interval', '/ˈkɒnfɪdəns ˈɪntəvəl/', 'noun', '{"zh-TW":["置信區間"],"en":["a range of values within which the true value is expected to fall with a stated probability"]}', NULL, 'calculate a confidence interval / 95% confidence interval', '[{"en":"The sales forecast has a 95% confidence interval of plus or minus 8%.","zh-TW":"銷售預測的置信區間為正負8%，置信水平95%。"},{"en":"Confidence intervals are used in market research to quantify estimate uncertainty.","zh-TW":"置信區間在市場研究中用於量化估計的不確定性。"}]', NULL, NULL, 5, 1395, NULL),
(1396, 'confident', '/ˈkɒnfɪdənt/', 'adjective', '{"zh-TW":["有自信的"],"en":["feeling sure about one''s own abilities"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"fid","meaning":"trust (信任)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"完全信任自己的，即「有自信的」。"}', 'feel confident / confident speaker', '[{"en":"She is confident about passing the exam.","zh-TW":"她對通過考試很有信心。"},{"en":"He gave a confident presentation.","zh-TW":"他做了一場充滿自信的報告。"}]', '{"noun":"confidence","adverb":"confidently"}', NULL, 3, 1396, NULL),
(1397, 'confidential', '/ˌkɒnfɪˈdenʃl/', 'adjective', '{"zh-TW":["機密的；保密的"],"en":["intended to be kept secret"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"fid","meaning":"trust (信任)"},"suffix":{"text":"-ential","meaning":"relating to (有關的)"},"logic":"完全信任下才能知道的，即「機密的」。"}', 'confidential information / strictly confidential / confidential agreement', '[{"en":"This document contains confidential information.","zh-TW":"此文件包含機密資訊。"},{"en":"All client records are treated as strictly confidential.","zh-TW":"所有客戶記錄均被視為嚴格保密。"}]', '{"noun":"confidentiality"}', NULL, 4, 1397, 304),
(1398, 'confidential information', '/ˌkɒnfɪˈdenʃəl ˌɪnfəˈmeɪʃən/', 'noun', '{"zh-TW":["機密信息"],"en":["sensitive data or knowledge that must not be disclosed to unauthorized parties"]}', NULL, 'protect confidential information / disclose confidential information', '[{"en":"All employees are required to protect confidential information from external parties.","zh-TW":"所有員工都必須保護機密信息不被外部人員獲取。"},{"en":"Sharing confidential information without consent violates the employment contract.","zh-TW":"未經同意分享機密信息違反了勞動合約。"}]', NULL, NULL, 5, 1398, NULL),
(1399, 'confidentiality', '/ˌkɒnfɪˌdɛnʃiˈælɪti/', 'noun', '{"zh-TW":["保密性；機密性"],"en":["the obligation not to disclose certain information"]}', NULL, 'confidentiality agreement / maintain confidentiality', '[{"en":"Employees must sign a confidentiality agreement.","zh-TW":"員工必須簽署保密協議。"},{"en":"The terms of the settlement are subject to strict confidentiality.","zh-TW":"和解條款受到嚴格保密限制。"}]', '{"adjective":"confidential","adverb":"confidentially"}', NULL, 5, 1399, 529);